import {
  Content,
  FunctionCall,
  FunctionResponse,
  GroundingMetadata,
  Part,
} from '@google/genai';

/**
 * Intermediate data that an agent generates on its way to a final answer.
 */
export interface IntermediateData {
  /** Tool use trajectory in chronological order. */
  toolUses: FunctionCall[];

  /** Tool response trajectory in chronological order. */
  toolResponses: FunctionResponse[];

  /**
   * Responses generated by sub-agents to convey progress or status, as tuples
   * of the authoring sub-agent name and the parts of the response.
   */
  intermediateResponses: Array<[string, Part[]]>;
}

/**
 * A record of a specific point in an agent's invocation.
 *
 * This is a projection of the `Event` data model for the eval system.
 */
export interface InvocationEvent {
  /** The name of the agent that authored this event. */
  author: string;

  /** The content of the event. */
  content?: Content;

  /** Grounding metadata attached to the event. */
  groundingMetadata?: GroundingMetadata;
}

/** A container for the events that occur during an invocation. */
export interface InvocationEvents {
  invocationEvents: InvocationEvent[];
}

/** The two shapes an invocation's intermediate data can take. */
export type IntermediateDataType = IntermediateData | InvocationEvents;

/**
 * A single invocation of the agent under test.
 *
 * `rubrics` and `appDetails` from `adk-python` are absent: they belong to the
 * rubric and app-details subsystems, which are not ported yet.
 */
export interface Invocation {
  /** Unique identifier for the invocation. */
  invocationId?: string;

  /** Content provided by the user in this invocation. */
  userContent: Content;

  /** Final response from the agent. */
  finalResponse?: Content;

  /** Intermediate steps generated as part of the agent's execution. */
  intermediateData?: IntermediateDataType;

  /** Timestamp of the invocation, intended for debugging. */
  creationTimestamp?: number;
}

/**
 * A scenario for a conversation between a simulated user and the agent under
 * test.
 *
 * `userPersona` from `adk-python` is absent: it belongs to the user-simulator
 * subsystem, which is not ported yet.
 */
export interface ConversationScenario {
  /** The fixed first user message given to the agent. */
  startingPrompt: string;

  /** The plan the user simulator follows as it plays out the conversation. */
  conversationPlan: string;
}
